/**
 * Errors surfaced to foreign code as exceptions.
 */
public 
enum GraphrtError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * The runtime configuration JSON is invalid.
     */
    case InvalidConfig(message: String
    )
    /**
     * The workflow document could not be parsed or compiled.
     */
    case InvalidWorkflow(message: String
    )
    /**
     * Run inputs, snapshot or selector JSON is invalid.
     */
    case InvalidInput(message: String
    )
    /**
     * A WebAssembly plugin could not be loaded.
     */
    case Plugin(message: String
    )
    /**
     * Internal failure (runtime could not start, lock poisoned...).
     */
    case Runtime(message: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension GraphrtError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeGraphrtError: FfiConverterRustBuffer {
    typealias SwiftType = GraphrtError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> GraphrtError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidConfig(
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .InvalidWorkflow(
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .InvalidInput(
            message: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Plugin(
            message: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Runtime(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: GraphrtError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .InvalidConfig(message):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .InvalidWorkflow(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .InvalidInput(message):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Plugin(message):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Runtime(message):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


